230	        pet.setType(findPetTypeById(pet.getType().getId()));
231	        petRepository.save(pet);
232	    }
233	
234	    @Override
235	    @Transactional
236	    public void saveVisit(Visit visit) throws DataAccessException {
237	        visitRepository.save(visit);
238	
239	    }
240	
241	    @Override
242	    @Transactional(readOnly = true)
243	    public Collection<Vet> findVets() throws DataAccessException {
244	        return vetRepository.findAll();
245	    }
246	
247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        ownerRepository.save(owner);
251	
252	    }
253	
254	    @Override
255	    @Transactional
256	    public void createOwner(Owner owner) throws DataAccessException {
257	        rejectWhenDailyLimitReached(owner);
258	        rejectWhenCityAtCapacity(owner);
259	        rejectWhenDuplicateIdentity(owner);
260	        owner.setHouseholdId(deriveHouseholdId(owner));
261	        List<Owner> householdMembers = findHouseholdMembers(owner);
262	        assignPossibleDuplicate(owner);
263	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
264	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
265	        if (owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(deduplicateCustomerCode(deriveCustomerCode(owner)));
267	        }
268	        if (owner.getNamesakeCount() == null) {
269	            owner.setNamesakeCount(countNamesakes(owner));
270	        }
271	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
272	        owner.setCapacityWarning(approachingCityCapacity(owner));
273	        ownerRepository.save(owner);
274	    }
275	
276	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
277	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
278	
279	    /**
280	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
281	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
282	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
283	     * today by the controller, determines which day is counted — the same accumulation path as the
284	     * daily-limit rule.
285	     */
286	    private boolean exceedsBulkSignupThreshold(Owner owner) {
287	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
288	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
289	    }
290	
291	    /**
292	     * Count the existing owners that already share this owner's first name and last name,
293	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
294	     * before the owner is persisted, so it reflects the owners present at creation time.
295	     */
296	    private int countNamesakes(Owner owner) {
297	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
298	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
299	        return (int) findActiveOwners().stream()
300	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
301	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
302	            .count();
303	    }
304	
305	    /**
306	     * The existing owners that have not been soft-deleted. Duplicate and identity checks run
307	     * against this set, so an owner flagged {@code deleted} (see {@link #deleteOwner(Owner)}) is
308	     * ignored and no longer blocks a create that would otherwise match it.
309	     */
310	    private List<Owner> findActiveOwners() {
311	        return ownerRepository.findAll().stream()
312	            .filter(existing -> !existing.isDeleted())
313	            .toList();
314	    }
315	
316	    /**
317	     * The existing owners that already belong to this owner's household, i.e. those carrying the
318	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
319	     * household id is derived purely from the normalized last name and postcode, this is exactly
320	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
321	     * persisted, so it reflects the owners present at creation time. The owner's own
322	     * {@code householdId} must already be assigned before calling.
323	     */
324	    private List<Owner> findHouseholdMembers(Owner owner) {
325	        String householdId = owner.getHouseholdId();
326	        return findActiveOwners().stream()
327	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
328	            .toList();
329	    }
330	
331	    /**
332	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
333	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
334	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
335	     * map to the same value automatically, without any opt-in, so they form one household.
336	     */
337	    private static String deriveHouseholdId(Owner owner) {
338	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
339	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
340	        return sha256HexPrefix(lastName + "|" + postcode, 12);
341	    }
342	
343	    /**
344	     * The membership-level ceiling for a new owner joining {@code householdMembers}: one above the
345	     * maximum membership level among the existing members. Returns {@code null} when the household
346	     * has no existing member, so no cap applies. Evaluated before the owner is persisted, so it
347	     * reflects the members (and their levels) present at creation time.
348	     */
349	    private Integer membershipLevelCap(List<Owner> householdMembers) {
350	        return householdMembers.stream()
351	            .map(MembershipLevels::level)
352	            .max(Integer::compareTo)
353	            .map(max -> max + 1)
354	            .orElse(null);
355	    }
356	
357	    /**
358	     * Reject the create with a {@code 409 Conflict} when the owner's derived {@code identityKey}
359	     * (see {@link IdentityKeyNormalizer}) exactly matches that of an existing, non-deleted owner.
360	     * This single key is the whole of duplicate detection: the former separate household-duplicate
361	     * block from the computed {@code householdId} no longer applies. Owners flagged {@code deleted}
362	     * are ignored (see {@link #findActiveOwners()}); the e-mail-domain blocklist is applied earlier,
363	     * before this method runs. Evaluated before the owner is persisted, so it reflects the owners
364	     * present at creation time.
365	     */
366	    private void rejectWhenDuplicateIdentity(Owner owner) {
367	        String identityKey = IdentityKeyNormalizer.derive(owner);
368	        boolean duplicate = findActiveOwners().stream()
369	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
370	        if (duplicate) {
371	            throw new DuplicateIdentityException(
372	                "an owner with the same identity key already exists");
373	        }
374	    }
375	
376	    /**
377	     * Set the new owner's soft-duplicate flags. Because the telephone is part of the
378	     * {@code identityKey}, two owners sharing a last name and postcode but with different telephones
379	     * are no longer a hard duplicate; they are surfaced as a soft match instead. The flag is raised
380	     * when the owner's {@code identityKey} differs from an existing, non-deleted owner's yet their
381	     * last-name {@link Soundex} codes and postcodes match, pointing {@code possibleDuplicateOf} at
382	     * that owner; otherwise both flags are cleared so the field is always present in the response.
383	     * Evaluated before the owner is persisted, so it reflects the owners present at creation time.
384	     */
385	    private void assignPossibleDuplicate(Owner owner) {
386	        String identityKey = IdentityKeyNormalizer.derive(owner);
387	        String soundex = Soundex.encode(owner.getLastName());
388	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
389	        Owner match = findActiveOwners().stream()
390	            .filter(existing -> !identityKey.equals(IdentityKeyNormalizer.derive(existing)))
391	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
392	            .filter(existing -> postcode.equals(existing.getPostcode() == null ? "" : existing.getPostcode()))
393	            .findFirst()
394	            .orElse(null);
395	        if (match != null) {
396	            owner.setPossibleDuplicate(true);
397	            owner.setPossibleDuplicateOf(match.getId());
398	        }
399	        else {
400	            owner.setPossibleDuplicate(false);
401	            owner.setPossibleDuplicateOf(null);
402	        }
403	    }
404	
405	    /** Maximum number of owners that may be created on any single day (by registration date). */
406	    private static final long DAILY_OWNER_LIMIT = 100L;
407	
408	    /**
409	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
410	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
411	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
412	     * to today by the controller, determines which day the limit is checked against.
413	     */
414	    private void rejectWhenDailyLimitReached(Owner owner) {
415	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
416	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
417	            throw new DailyOwnerLimitExceededException(
418	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
419	        }
420	    }
421	
422	    /**
423	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
424	     * before the owner is persisted, so it reflects the owners present at creation time.
425	     */
426	    private long countOwnersRegisteredOn(LocalDate day) {
427	        return ownerRepository.findAll().stream()
428	            .filter(existing -> day.equals(existing.getRegistrationDate()))
429	            .count();
430	    }
431	
432	    /** Maximum number of owners allowed to live in any single city. */
433	    private static final long CITY_CAPACITY = 50L;
434	
435	    /**
436	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
437	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
438	     * is persisted, so it reflects the owners present at creation time.
439	     */
440	    private void rejectWhenCityAtCapacity(Owner owner) {
441	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
442	            throw new CityCapacityExceededException(
443	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
444	        }
445	    }
446	
447	    /**
448	     * Lower bound (inclusive) of the range of existing owners in a city that raises the
449	     * capacity warning. Between this and {@code CITY_CAPACITY - 1} the city is approaching its
450	     * {@value #CITY_CAPACITY} limit.
451	     */
452	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
453	
454	    /**
455	     * Whether the owner's city already contains between {@value #CITY_CAPACITY_WARNING_THRESHOLD}
456	     * and {@code CITY_CAPACITY - 1} owners (approaching, but not at, the {@value #CITY_CAPACITY}
457	     * capacity limit), compared case-insensitively with collapsed whitespace. Evaluated before the
458	     * owner is persisted, so it reflects the owners present at creation time. The hard rejection at
459	     * {@value #CITY_CAPACITY} runs earlier (see {@link #rejectWhenCityAtCapacity(Owner)}), so the
460	     * count is always below capacity when this is reached.
461	     */
462	    private boolean approachingCityCapacity(Owner owner) {
463	        long count = countOwnersInCity(owner);
464	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
465	    }
466	
467	    /**
468	     * Count the existing owners that already live in this owner's city, compared
469	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
470	     * owner is persisted, so it reflects the owners present at creation time.
471	     */
472	    private long countOwnersInCity(Owner owner) {
473	        String city = IdentityNormalizer.normalize(owner.getCity());
474	        return ownerRepository.findAll().stream()
475	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
476	            .count();
477	    }
478	
479	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
480	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
481	        "NSW", new int[] {2000, 2099},
482	        "VIC", new int[] {3000, 3099},
483	        "QLD", new int[] {4000, 4099});
484	
485	    /** Region code used when the postcode maps to no known region (or is absent). */
486	    private static final String UNKNOWN_REGION = "UNKNOWN";
487	
488	    /**
489	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
490	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
491	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
492	     * name. No sequence number is used; the identity is fully derived from the region and hash.
493	     */
494	    private String deriveCustomerCode(Owner owner) {
495	        String region = regionForPostcode(owner.getPostcode());
496	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
497	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
498	        return region + "-" + sha256Hex8(telephone + lastName);
499	    }
500	
501	    /**
502	     * De-duplicates a computed {@code customerCode} against the existing owners: if no owner already
503	     * carries {@code baseCode} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
504	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
505	     * owner is persisted, so it reflects the owners present at creation time.
506	     */
507	    private String deduplicateCustomerCode(String baseCode) {
508	        Set<String> existingCodes = findActiveOwners().stream()
509	            .map(Owner::getCustomerCode)
510	            .filter(Objects::nonNull)
511	            .collect(Collectors.toSet());
512	        if (!existingCodes.contains(baseCode)) {
513	            return baseCode;
514	        }
515	        int n = 2;
516	        while (existingCodes.contains(baseCode + "-" + n)) {
517	            n++;
518	        }
519	        return baseCode + "-" + n;
520	    }
521	
522	    /**
523	     * Returns the region code whose inclusive postcode range contains {@code postcode}
524	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
525	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
526	     */
527	    private static String regionForPostcode(String postcode) {
528	        if (postcode == null || !postcode.matches("\\d{4}")) {
529	            return UNKNOWN_REGION;
530	        }
531	        int value = Integer.parseInt(postcode);
532	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
533	            int[] range = entry.getValue();
534	            if (value >= range[0] && value <= range[1]) {
535	                return entry.getKey();
536	            }
537	        }
538	        return UNKNOWN_REGION;
539	    }
540	
541	    /**
542	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
543	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
544	     */
545	    private static String sha256Hex8(String value) {
546	        return sha256HexPrefix(value, 8).toUpperCase();
547	    }
548	
549	    /**
550	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
551	     * the UTF-8 bytes of {@code value}.
552	     */
553	    private static String sha256HexPrefix(String value, int hexChars) {
554	        try {
555	            byte[] digest = MessageDigest.getInstance("SHA-256")
556	                .digest(value.getBytes(StandardCharsets.UTF_8));
557	            StringBuilder sb = new StringBuilder(hexChars);
558	            for (int i = 0; sb.length() < hexChars; i++) {
559	                sb.append(String.format("%02x", digest[i]));
560	            }
561	            return sb.substring(0, hexChars);
562	        }
563	        catch (NoSuchAlgorithmException e) {
564	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
565	        }
566	    }
567	
568	    @Override
569	    @Transactional(readOnly = true)
570	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
571	        return ownerRepository.findByLastName(lastName);
572	    }
573	
574	    @Override
575	    @Transactional(readOnly = true)
576	    public Collection<Visit> findVisitsByPetId(int petId) {
577	        return visitRepository.findByPetId(petId);
578	    }
579	
580	    @Override
581	    @Transactional(readOnly = true)
582	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
583	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
584	    }
585	
586	    private <T> T findEntityById(Supplier<T> supplier) {
587	        try {
588	            return supplier.get();
589	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
590	            // Just ignore not found exceptions for Jdbc/Jpa realization
591	            return null;
592	        }
593	    }
594	
595	}
