126	     * and the last two digits of the fiscal year derived from the (business-day-adjusted)
127	     * registrationDate. The fiscal year starts on 1 July. Returns {@code null} when no registration
128	     * date is present.
129	     */
130	    default String fiscalYear(Owner owner) {
131	        if (owner == null || owner.getRegistrationDate() == null) {
132	            return null;
133	        }
134	        return "FY" + fiscalYearYY(owner.getRegistrationDate());
135	    }
136	
137	    /**
138	     * Formats the last two digits (zero-padded) of the fiscal year that {@code date} falls in.
139	     */
140	    private String fiscalYearYY(LocalDate date) {
141	        return String.format("%02d", RegistrationDateNormalizer.fiscalYear(date) % 100);
142	    }
143	
144	    /**
145	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
146	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
147	     */
148	    default Integer checkDigit(Owner owner) {
149	        if (owner == null || owner.getCustomerCode() == null) {
150	            return null;
151	        }
152	        String code = owner.getCustomerCode();
153	        int sum = 0;
154	        boolean dbl = true;
155	        for (int i = code.length() - 1; i >= 0; i--) {
156	            char c = code.charAt(i);
157	            if (c < '0' || c > '9') {
158	                continue;
159	            }
160	            int d = c - '0';
161	            if (dbl) {
162	                d *= 2;
163	                if (d > 9) {
164	                    d -= 9;
165	                }
166	            }
167	            sum += d;
168	            dbl = !dbl;
169	        }
170	        return (10 - (sum % 10)) % 10;
171	    }
172	
173	    /**
174	     * The owner's membership points; see {@link MembershipLevels#points(Owner)}.
175	     */
176	    default Integer membershipPoints(Owner owner) {
177	        return MembershipLevels.points(owner);
178	    }
179	
180	    /**
181	     * The owner's capped numeric membership level; see {@link MembershipLevels#level(Owner)}.
182	     */
183	    default Integer membershipLevel(Owner owner) {
184	        return MembershipLevels.level(owner);
185	    }
186	
187	    /**
188	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
189	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
190	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
191	     */
192	    default String locality(Owner owner) {
193	        if (owner == null) {
194	            return null;
195	        }
196	        String code = owner.getCustomerCode();
197	        if (code == null) {
198	            return "UNKNOWN";
199	        }
200	        int dash = code.indexOf('-');
201	        return dash >= 0 ? code.substring(0, dash) : code;
202	    }
203	
204	    /**
205	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
206	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
207	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
208	     */
209	    default String timezone(Owner owner) {
210	        if (owner == null) {
211	            return null;
212	        }
213	        String region = locality(owner);
214	        return switch (region) {
215	            case "NSW" -> "Australia/Sydney";
216	            case "VIC" -> "Australia/Melbourne";
217	            case "QLD" -> "Australia/Brisbane";
218	            default -> null;
219	        };
220	    }
221	
222	    /**
223	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
224	     * on its registration day at creation time). A {@code null} stored value is treated as
225	     * {@code false}, so the field is always present in the response.
226	     */
227	    default Boolean bulkSignupWarning(Owner owner) {
228	        if (owner == null) {
229	            return null;
230	        }
231	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
232	    }
233	
234	    /**
235	     * Whether the owner carries the capacity warning (its city already held between 40 and 49
236	     * owners, approaching the capacity limit of 50, at creation time). A {@code null} stored value
237	     * is treated as {@code false}, so the field is always present in the response.
238	     */
239	    default Boolean capacityWarning(Owner owner) {
240	        if (owner == null) {
241	            return null;
242	        }
243	        return Boolean.TRUE.equals(owner.getCapacityWarning());
244	    }
245	
246	    /**
247	     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
248	     * duplicate, but sharing an existing owner's last-name Soundex code and postcode while differing
249	     * on the identity key (typically a different telephone). A {@code null} stored value is treated
250	     * as {@code false}, so the field is always present in the response.
251	     */
252	    default Boolean possibleDuplicate(Owner owner) {
253	        if (owner == null) {
254	            return null;
255	        }
256	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
257	    }
258	
259	    /**
260	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
261	     * present, otherwise {@code PHONE}.
262	     */
263	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
264	        if (owner == null) {
265	            return null;
266	        }
267	        String email = owner.getEmail();
268	        return (email != null && !email.isEmpty())
269	            ? OwnerDto.ContactPreferenceEnum.EMAIL
270	            : OwnerDto.ContactPreferenceEnum.PHONE;
271	    }
272	
