130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
133	        String idempotencyKey = request.getHeader("Idempotency-Key");
134	        ResponseEntity<OwnerDto> replayed = replayIdempotent(idempotencyKey);
135	        if (replayed != null) {
136	            return replayed;
137	        }
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
141	        owner.setTelephone(telephone);
142	        String email = EmailNormalizer.normalize(owner.getEmail());
143	        owner.setEmail(email);
144	        normalizeAddress(owner);
145	        PostcodeValidator.validate(owner.getPostcode(), owner.getCity());
146	        RegistrationDateValidator.validate(owner.getRegistrationDate());
147	        LocalDate effectiveRegistrationDate =
148	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
149	        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
150	        this.clinicService.createOwner(owner);
151	        Integer membershipLevel = ownerMapper.membershipLevel(owner);
152	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
154	            membershipLevel, ownerMapper.membershipNumber(owner));
155	        OwnerCreatedAuditEvent event = new OwnerCreatedAuditEvent(AUDIT_SEQ.incrementAndGet(),
156	            owner.getId(), owner.getCustomerCode(), membershipLevel);
157	        AUDIT.info(objectMapper.writeValueAsString(event));
158	        idempotencyStore.remember(idempotencyKey, owner.getId());
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
