165	    /**
166	     * When {@code idempotencyKey} names a create that already succeeded, return the originally
167	     * created owner with {@code 200 OK} so the repeat is not persisted as a duplicate. Returns
168	     * {@code null} when there is no key or none has been seen, so the caller proceeds with a
169	     * normal create.
170	     */
171	    private ResponseEntity<OwnerDto> replayIdempotent(String idempotencyKey) {
172	        return idempotencyStore.find(idempotencyKey)
173	            .map(this.clinicService::findOwnerById)
174	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
175	            .orElse(null);
176	    }
177	
178	    /**
179	     * Normalizes the owner's address, preferring the structured form. When a non-blank
180	     * {@code addressLine1} is supplied, both structured lines are normalized and the flat
181	     * {@code address} is composed from them: the normalized {@code addressLine1}, and — when
182	     * {@code addressLine2} is present — a single space followed by the normalized
183	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized on its own,
184	     * preserving backward compatibility. Either way a blank address is rejected with a
185	     * {@code 400 Bad Request} by {@link AddressNormalizer#normalize(String)}.
186	     */
187	    private void normalizeAddress(Owner owner) {
188	        String addressLine1 = owner.getAddressLine1();
189	        if (addressLine1 != null && !addressLine1.isBlank()) {
190	            String line1 = AddressNormalizer.normalize(addressLine1);
191	            owner.setAddressLine1(line1);
192	            String addressLine2 = owner.getAddressLine2();
193	            if (addressLine2 != null && !addressLine2.isBlank()) {
194	                String line2 = AddressNormalizer.normalize(addressLine2);
195	                owner.setAddressLine2(line2);
196	                owner.setAddress(line1 + " " + line2);
197	            } else {
198	                owner.setAddressLine2(null);
199	                owner.setAddress(line1);
200	            }
201	        } else {
202	            owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
203	        }
204	    }
